//! The model's search over the real machine.
//!
//! The environment, the bounds and the checks are those of the executable
//! model, `design/installation-machine-model-next.py` of the notes; its
//! step is the Rust machine, built from a state of the model and read back
//! into one. The table the search finds is compared, line for line, with
//! the model's own output (`tests/model-table.txt`, generated by `python3
//! -I design/installation-machine-model-next.py --table` and never edited).

extern crate std;

use oer_protocols_ieee80211_contracts_port::GateClosed;
use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet, VecDeque};
use std::string::{String, ToString};
use std::vec::Vec;
use std::{format, vec};

use super::*;
use oer_protocols_ieee80211_contracts_port::life::{PortKey, forge};

/// The channel a run asks.
const CHANNEL: u8 = 6;
/// The instant of every step but a deadline's.
const NOW: Instant = Instant::from_micros(0);
/// Every request's deadline in the search: the instant of the model's
/// `deadline`.
const DEADLINE: Instant = Instant::from_micros(1_000_000);

type M<'id> = Machine<'id, u8, ()>;

/// A state of the model: `pos goal data tokens net wait`.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
struct S {
    pos: &'static str,
    goal: Option<&'static str>,
    data: &'static str,
    tokens: &'static str,
    net: Option<&'static str>,
    wait: Option<&'static str>,
}

/// A port's key and a stopped radio, made for one use.
fn key<'id>() -> (PortKey<'id>, Stopped<'id>, StopRight<'id>) {
    forge()
}

fn running<'id>() -> Running<'id> {
    let (key, stopped, _) = key();
    key.started(key.start(stopped))
}

/// The machine in the model's state `s`, its request's deadline `deadline`.
fn build<'id>(s: &S, deadline: Option<Instant>) -> M<'id> {
    let (key, stopped, right) = key();
    let at = match s.pos {
        "stopped" => Some(At::Stopped(stopped)),
        "starting" => Some(At::Starting(key.start(stopped))),
        "running" => Some(At::Running(running())),
        "retuning" => Some(At::Retuning(key.retune(running()))),
        "stopping" => Some(At::Stopping(Stopping::from(running()))),
        "retired" => Some(At::Retired(key.retire(stopped, key.units_home()))),
        "released" => None,
        other => panic!("no position {other}"),
    };
    let data = match (s.data, s.pos) {
        (_, "retired") => Data::Retired,
        ("flowing", _) => Data::Flowing,
        ("stopping", _) => Data::Stopping,
        _ => Data::Stopped(()),
    };
    let tokens = match s.tokens {
        "held" => Tokens::Held,
        "asked" => Tokens::Asked,
        _ => Tokens::Ended,
    };
    let life = match at {
        Some(at) => Life::Port {
            right,
            at,
            data,
            tokens,
        },
        None => Life::Released,
    };
    let want = |goal: &str| match goal {
        "run" => Want::Run(CHANNEL),
        "halt" => Want::Halt,
        "release_stays" => Want::Release(NetworkStep::Stays),
        "release_stops" => Want::Release(match s.net {
            Some("stopped") => NetworkStep::Stopped,
            _ => NetworkStep::Told,
        }),
        other => panic!("no goal {other}"),
    };
    Machine {
        life,
        goal: match s.goal {
            None => Goal::None,
            Some("service") => Goal::Service,
            Some(goal) => Goal::Open {
                want: want(goal),
                deadline,
            },
        },
        waiting: match s.wait {
            None => Waited::Nothing,
            Some("units") => Waited::Units,
            Some(other) => panic!("no wait {other}"),
        },
    }
}

fn position_name(position: Position) -> &'static str {
    match position {
        Position::Stopped => "stopped",
        Position::Starting => "starting",
        Position::Running => "running",
        Position::Retuning => "retuning",
        Position::Stopping => "stopping",
        Position::Retired => "retired",
    }
}

fn data_name(data: &Data<()>) -> &'static str {
    match data {
        Data::Flowing => "flowing",
        Data::Stopping => "stopping",
        Data::Stopped(()) | Data::Retired => "stopped",
    }
}

fn tokens_name(tokens: Tokens) -> &'static str {
    match tokens {
        Tokens::Held => "held",
        Tokens::Asked => "asked",
        Tokens::Ended => "ended",
    }
}

/// The model's state of the machine.
fn project(m: &M<'_>) -> S {
    let (pos, data, tokens) = match &m.life {
        Life::Port {
            at, data, tokens, ..
        } => (
            position_name(at.position()),
            data_name(data),
            tokens_name(*tokens),
        ),
        Life::Releasing | Life::Released => ("released", "stopped", "ended"),
    };
    project_parts(pos, data, tokens, &m.goal, m.waiting)
}

/// The model's state of the view of a port that holds an installation.
fn project_port(port: &Port<'_, '_, u8, ()>) -> S {
    project_parts(
        position_name(port.at.position()),
        data_name(port.data),
        tokens_name(*port.tokens),
        port.goal,
        *port.waiting,
    )
}

fn project_parts(
    pos: &'static str,
    data: &'static str,
    tokens: &'static str,
    goal: &Goal<u8>,
    waiting: Waited,
) -> S {
    let (goal, net) = match *goal {
        Goal::None => (None, None),
        Goal::Service => (Some("service"), None),
        Goal::Open { want, .. } => match want {
            Want::Run(_) => (Some("run"), None),
            Want::Halt => (Some("halt"), None),
            Want::Release(NetworkStep::Stays) => (Some("release_stays"), None),
            Want::Release(NetworkStep::Told) => (Some("release_stops"), Some("told")),
            Want::Release(NetworkStep::Stopped) => (Some("release_stops"), Some("stopped")),
        },
    };
    S {
        pos,
        goal,
        data,
        tokens,
        net,
        wait: match waiting {
            Waited::Nothing => None,
            Waited::Units => Some("units"),
        },
    }
}

/// One item of a step's trace.
#[derive(Clone, Debug)]
enum Item {
    Ask {
        name: &'static str,
        proof: Option<&'static str>,
        at: S,
    },
    Answer {
        name: &'static str,
        answer: &'static str,
    },
    /// A message, and the state when it was passed.
    Tell(&'static str, S),
    /// The end's name, and the class of the permit it returned.
    End(&'static str, Option<&'static str>),
    Report(String),
}

/// The model's input: its kind, and a request's name.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct In {
    kind: &'static str,
    request: &'static str,
}

impl In {
    const fn of(kind: &'static str) -> Self {
        Self { kind, request: "" }
    }

    /// The model's `inp[-1]`.
    fn last(&self) -> &'static str {
        if self.kind == "request" {
            self.request
        } else {
            self.kind
        }
    }
}

fn live<'id>(pos: &str) -> Live<'id> {
    if pos == "running" {
        Live::Running(LiveRunning { brand: PhantomData })
    } else {
        Live::Stopped(LiveStopped { brand: PhantomData })
    }
}

fn permit_for<'id>(pos: &str, held: Option<&str>) -> Permit<'id> {
    match held {
        Some("live") => Permit::Live(live(pos)),
        _ => Permit::Spent(Spent { brand: PhantomData }),
    }
}

/// The Rust input of the model's, and the instant of its step: a run of a
/// running radio is a retune, asked under the installation's closed gate.
fn input<'g, 'id>(
    inp: In,
    pos: &str,
    permit: Option<&str>,
    gate: &'g GateClosed<'id>,
    deadline: Option<Instant>,
) -> (Input<'g, 'id, u8>, Instant) {
    match inp.kind {
        "request" => {
            let request = match inp.request {
                "run" if pos == "running" => Request::retune(
                    LiveRunning { brand: PhantomData },
                    CHANNEL,
                    gate.lent(),
                    deadline,
                ),
                "run" => Request::run(LiveStopped { brand: PhantomData }, CHANNEL, deadline),
                "halt" => Request::halt(live(pos), deadline),
                "release_stays" => {
                    Request::release(permit_for(pos, permit), Network::Stays, deadline)
                }
                "release_stops" => {
                    Request::release(permit_for(pos, permit), Network::Stops, deadline)
                }
                other => panic!("no request {other}"),
            };
            (Input::Request(request), NOW)
        }
        "turn" => (Input::Turn, NOW),
        "deadline" => (Input::Turn, deadline.unwrap_or(DEADLINE)),
        "needs_stop" => (Input::NeedsStop, NOW),
        "tokens_ended" => (Input::TokensEnded(TokensEnded { brand: PhantomData }), NOW),
        "network_stopped" => (Input::NetworkStopped, NOW),
        other => panic!("no input {other}"),
    }
}

/// How a run of one step ended.
enum Ran {
    /// The state after the step, its trace, the model's name of its rest,
    /// the rest itself and the deadline of the request open after it.
    Done(S, Vec<Item>, &'static str, Rest, Option<Instant>),
    Need(&'static str),
}

fn end_name(ended: &Ended<'_>) -> &'static str {
    match ended {
        Ended::Request(Ok(End::Started), _) => "ok/started",
        Ended::Request(Ok(End::Halted), _) => "ok/halted",
        Ended::Released => "ok/released",
        Ended::Request(Err(Unreached::StartRefused(_)), _) => "err/start_refused",
        Ended::Request(Err(Unreached::StartInterrupted), _) => "err/start_interrupted",
        Ended::Request(Err(Unreached::Deadline(_)), _) => "err/deadline",
    }
}

/// The class of the permit an end returned.
fn returned(ended: &Ended<'_>) -> Option<&'static str> {
    match ended {
        Ended::Request(_, Permit::Live(_)) => Some("live"),
        Ended::Request(_, Permit::Spent(_)) => Some("spent"),
        Ended::Released => None,
    }
}

/// Run one step of the machine in state `s` with the answers given: what it
/// did, or the ask it stops at.
fn run(
    s: &S,
    inp: In,
    permit: Option<&str>,
    answers: &[&'static str],
    deadline: Option<Instant>,
    gate: &GateClosed<'_>,
) -> Ran {
    let mut machine = build(s, deadline);
    let (rust, now) = input(inp, s.pos, permit, gate, deadline);
    let (key, _, _) = key();
    let mut trace = Vec::new();
    let mut feed = answers.iter().copied();
    let mut step = machine.step(rust, now);
    macro_rules! ask {
        ($name:expr, $proof:expr, $at:expr) => {{
            trace.push(Item::Ask {
                name: $name,
                proof: $proof,
                at: $at,
            });
            let Some(answer) = feed.next() else {
                return Ran::Need($name);
            };
            trace.push(Item::Answer {
                name: $name,
                answer,
            });
            answer
        }};
    }
    loop {
        step = match step {
            Step::Start(ask, resume) => {
                let proof = match &ask {
                    StartAsk::Begin(..) => "stopped",
                    StartAsk::Poll(_) => "starting",
                };
                let answer = ask!("start", Some(proof), project_port(&resume.port));
                let _asked = ask;
                resume.answer(match answer {
                    "started" => StartPoll::Running(running()),
                    "pending" => StartPoll::Pending(key.start(self::key().1)),
                    _ => StartPoll::Stopped(self::key().1, StartFailure::Phy),
                })
            }
            Step::Retune(ask, resume) => {
                let proof = match &ask {
                    RetuneAsk::Begin(..) => "running",
                    RetuneAsk::Poll(_) => "retuning",
                };
                let answer = ask!("retune", Some(proof), project_port(&resume.port));
                let _asked = ask;
                resume.answer(match answer {
                    "retuned" => RetunePoll::Running(running()),
                    "pending" => RetunePoll::Pending(key.retune(running())),
                    _ => RetunePoll::Stopped(self::key().1, StartFailure::Phy),
                })
            }
            Step::Stop(ask, mut resume) => {
                let proof = match &ask {
                    StopAsk::Running(_) => "running",
                    StopAsk::Starting(_) => "starting",
                    StopAsk::Retuning(_) => "retuning",
                    StopAsk::Poll(_) => "stopping",
                };
                let _right = resume.right();
                let answer = ask!("stop", Some(proof), project_port(&resume.port));
                let _asked = ask;
                resume.answer(match answer {
                    "ok" => StopPoll::Stopped(self::key().1),
                    _ => StopPoll::Pending(Stopping::from(running())),
                })
            }
            Step::StopData(resume) => {
                let answer = ask!("stop_data", None, project_port(&resume.port));
                resume.answer(match answer {
                    "stopped" => DataStop::Stopped(()),
                    _ => DataStop::Going,
                })
            }
            Step::UnitsHome(resume) => {
                let answer = ask!("units_home", None, project_port(&resume.port));
                match answer {
                    "home" => resume.home(key.units_home()),
                    _ => resume.pending(),
                }
            }
            Step::Retire(stopped, (), units, resume) => {
                let _answer = ask!("retire", Some("stopped"), project_port(&resume.port));
                resume.answer(key.retire(stopped, units))
            }
            Step::Release(retired, right, releasing) => {
                let _answer = ask!("release", Some("retired"), project(releasing.machine));
                key.release(retired, right);
                releasing.answer()
            }
            Step::Released(ended, rest) => {
                trace.push(Item::End(end_name(&ended), returned(&ended)));
                Step::Rest(rest)
            }
            Step::Tell(tell, resume) => {
                let at = project_port(&resume.port);
                trace.push(Item::Tell(
                    match tell {
                        Tell::EndTokens(_) => "end_tokens",
                        Tell::StopNetwork => "stop_network",
                        Tell::DataFlows(()) => "data_flows",
                    },
                    at,
                ));
                resume.go()
            }
            Step::Ended(ended, resume) => {
                trace.push(Item::End(end_name(&ended), returned(&ended)));
                resume.go()
            }
            Step::Interrupted(resume) => {
                trace.push(Item::Report("interrupted".to_string()));
                resume.go()
            }
            Step::Held(resume) => {
                trace.push(Item::Report(match resume.waiting() {
                    Waited::Units => "held/units".to_string(),
                    Waited::Nothing => "held/None".to_string(),
                }));
                resume.go()
            }
            Step::Rest(rest) => {
                let named = match rest {
                    Rest::Round => "round",
                    Rest::Wake(_) => "wake",
                };
                let after = machine.goal.deadline();
                return Ran::Done(project(&machine), trace, named, rest, after);
            }
        };
    }
}

fn answers_of(name: &str) -> &'static [&'static str] {
    match name {
        "start" => &["started", "pending", "refused"],
        "retune" => &["retuned", "pending", "failed"],
        "stop" => &["ok", "pending"],
        "stop_data" => &["stopped", "going"],
        "units_home" => &["home", "pending"],
        "retire" => &["ok"],
        "release" => &["ok"],
        other => panic!("no ask {other}"),
    }
}

/// What the bound of refusals counts: the hardware's failures.
fn refusal(name: &str, answer: &str) -> bool {
    matches!((name, answer), ("start", "refused") | ("retune", "failed"))
}

/// The right an answer gives.
fn gives(name: &str, answer: &str) -> Option<Option<&'static str>> {
    match (name, answer) {
        ("start", "started") | ("retune", "retuned") => Some(Some("running")),
        ("start", "pending") => Some(Some("starting")),
        ("retune", "pending") => Some(Some("retuning")),
        ("start", "refused") | ("retune", "failed") | ("stop", "ok") => Some(Some("stopped")),
        ("stop", "pending") => Some(Some("stopping")),
        ("retire", "ok") => Some(Some("retired")),
        ("release", "ok") => Some(None),
        _ => None,
    }
}

fn wakes(name: &str, answer: &str) -> bool {
    matches!(
        (name, answer),
        ("start" | "retune" | "stop", "pending")
            | ("stop_data", "going")
            | ("units_home", "pending")
    )
}

fn holds(pos: &str) -> Option<&'static str> {
    match pos {
        "stopped" => Some("stopped"),
        "starting" => Some("starting"),
        "running" => Some("running"),
        "retuning" => Some("retuning"),
        "stopping" => Some("stopping"),
        "retired" => Some("retired"),
        _ => None,
    }
}

const RETIRES: [&str; 2] = ["release_stays", "release_stops"];
const LIVE: [&str; 4] = ["run", "halt", "release_stays", "release_stops"];
const ENDS: [&str; 4] = ["halt", "service", "release_stays", "release_stops"];

/// The class of the permit an end returns.
fn permit(s: &S) -> Option<&'static str> {
    if s.pos == "released" {
        None
    } else if s.pos == "retired" || s.tokens != "held" {
        Some("spent")
    } else {
        Some("live")
    }
}

fn allowed(permit: Option<&str>) -> &'static [&'static str] {
    match permit {
        Some("live") => &LIVE,
        Some("spent") => &RETIRES,
        _ => &[],
    }
}

type Budget = (u32, u32, u32, u32);

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct Env {
    s: S,
    budget: Budget,
    open: Option<&'static str>,
    /// The controller was told to end this installation's tokens and has
    /// not yet.
    tok: bool,
    /// The network was told to stop and has not yet said so.
    net: bool,
    /// The last rest named a turn.
    turn: bool,
    permit: Option<&'static str>,
    /// The controller holds this installation's tokens.
    live: bool,
    /// The transmit gate as the controller holds it: closed from a retune
    /// it asks until a radio runs again.
    gate_closed: bool,
}

/// Every way one step can go.
fn steps(
    env: &Env,
    inp: In,
    nref: u32,
    gate: &GateClosed<'_>,
) -> Vec<(S, Vec<Item>, &'static str, Rest, Option<Instant>, u32)> {
    let mut ways = Vec::new();
    let mut stack: Vec<(Vec<&'static str>, u32)> = vec![(Vec::new(), 0)];
    while let Some((answers, used)) = stack.pop() {
        match run(&env.s, inp, env.permit, &answers, Some(DEADLINE), gate) {
            Ran::Done(s, trace, named, rest, after) => {
                ways.push((s, trace, named, rest, after, used));
            }
            Ran::Need(name) => {
                for &answer in answers_of(name) {
                    let cost = u32::from(refusal(name, answer));
                    if used + cost <= nref {
                        let mut next = answers.clone();
                        next.push(answer);
                        stack.push((next, used + cost));
                    }
                }
            }
        }
    }
    ways
}

fn inputs(env: &Env) -> Vec<(In, Budget)> {
    let (nreq, nind, nlate, nref) = env.budget;
    let mut out = Vec::new();
    if env.turn {
        out.push((In::of("turn"), env.budget));
    } else if nlate > 0 {
        out.push((In::of("turn"), (nreq, nind, nlate - 1, nref)));
    }
    if env.open.is_none() && nreq > 0 {
        for &request in allowed(env.permit) {
            out.push((
                In {
                    kind: "request",
                    request,
                },
                (nreq - 1, nind, nlate, nref),
            ));
        }
    }
    if nind > 0 && matches!(env.s.pos, "starting" | "running" | "retuning" | "stopping") {
        out.push((In::of("needs_stop"), (nreq, nind - 1, nlate, nref)));
    }
    if env.tok {
        out.push((In::of("tokens_ended"), env.budget));
    } else if nlate > 0 && env.live {
        out.push((In::of("tokens_ended"), (nreq, nind, nlate - 1, nref)));
    }
    if env.net {
        out.push((In::of("network_stopped"), env.budget));
    } else if nlate > 0 {
        out.push((In::of("network_stopped"), (nreq, nind, nlate - 1, nref)));
    }
    if nlate > 0 && env.open.is_some() {
        out.push((In::of("deadline"), (nreq, nind, nlate - 1, nref)));
    }
    out
}

fn quiet(env: &Env) -> bool {
    let s = &env.s;
    if s.goal.is_some() || env.open.is_some() {
        return false;
    }
    s.pos == "released"
        || (s.data != "stopping" && matches!(s.pos, "stopped" | "running" | "retired"))
}

type Table = BTreeMap<
    (&'static str, &'static str, &'static str),
    BTreeSet<(Vec<&'static str>, &'static str, Vec<String>, &'static str)>,
>;

struct Search {
    seen: usize,
    machine_states: usize,
    longest: usize,
    problems: BTreeMap<&'static str, usize>,
    dead: usize,
    table: Table,
}

#[allow(clippy::too_many_lines, reason = "the model's search, check by check")]
fn explore(budget: Budget, gate: &GateClosed<'_>) -> Search {
    let first = Env {
        s: S {
            pos: "stopped",
            goal: None,
            data: "stopped",
            tokens: "held",
            net: None,
            wait: None,
        },
        budget,
        open: None,
        tok: false,
        net: false,
        turn: false,
        permit: Some("live"),
        live: true,
        gate_closed: false,
    };
    let mut seen = HashSet::from([first]);
    let mut queue = VecDeque::from([first]);
    let mut edges: HashMap<Env, Vec<Env>> = HashMap::new();
    let mut problems: BTreeMap<&'static str, usize> = BTreeMap::new();
    let mut problem = |kind: &'static str| *problems.entry(kind).or_default() += 1;
    let mut table: Table = BTreeMap::new();
    let mut longest = 0;
    while let Some(env) = queue.pop_front() {
        let mut outs = Vec::new();
        for (inp, budget2) in inputs(&env) {
            let s = env.s;
            for (ns, trace, rest, raw, after, used) in steps(&env, inp, budget2.3, gate) {
                let (mut opened, mut tok, mut net, mut holds_permit, mut live) =
                    (env.open, env.tok, env.net, env.permit, env.live);
                let mut gate_closed = env.gate_closed;
                let mut told = false;
                if inp.kind == "request" && inp.request == "run" && s.pos == "running" {
                    // A retune is asked under a closed gate.
                    gate_closed = true;
                }
                if inp.kind == "request" {
                    if opened.is_some() {
                        problem("two requests open");
                    }
                    if s.pos != "released" && !allowed(permit(&s)).contains(&inp.request) {
                        problem("a request the machine cannot serve");
                    }
                    opened = Some(inp.request);
                }
                if inp.kind == "tokens_ended" {
                    tok = false;
                    live = false;
                    if opened.is_none() && holds_permit == Some("live") {
                        holds_permit = Some("spent");
                    }
                }
                if inp.kind == "network_stopped" {
                    net = false;
                }
                let mut asked: Vec<&str> = Vec::new();
                let mut held = holds(s.pos);
                let (mut ends, mut woken, mut home) = (0, false, false);
                let mut returned = None;
                for item in &trace {
                    match item {
                        Item::Ask { name, proof, at } => {
                            if asked.contains(name) {
                                problem("asked twice in a step");
                            }
                            asked.push(name);
                            if let Some(proof) = proof {
                                if held != Some(proof) {
                                    problem("ask without its right");
                                }
                                held = None;
                            }
                            let proof = proof.unwrap_or("");
                            if *name == "start" && !matches!(proof, "stopped" | "starting") {
                                problem("a start from a wrong position");
                            }
                            if *name == "stop"
                                && !matches!(
                                    proof,
                                    "running" | "starting" | "retuning" | "stopping"
                                )
                            {
                                problem("a stop from a wrong position");
                            }
                            if *name == "retune" && !matches!(proof, "running" | "retuning") {
                                problem("a retune from a wrong position");
                            }
                            if *name == "retune" && !gate_closed {
                                problem("a retune asked with the gate open");
                            }
                            if *name == "retire"
                                && !(at.data == "stopped" && at.tokens == "ended" && home)
                            {
                                problem("retire asked early");
                            }
                            if *name == "retire" && live {
                                problem("retire asked with the tokens out");
                            }
                            if *name == "release"
                                && at.goal == Some("release_stops")
                                && at.net != Some("stopped")
                            {
                                problem("release before the network stopped");
                            }
                            if *name == "start" && at.data == "stopping" {
                                problem("start while the data is stopping");
                            }
                            if *name == "stop"
                                && proof == "running"
                                && (!at.goal.is_some_and(|goal| ENDS.contains(&goal))
                                    || at.data == "flowing")
                            {
                                problem(
                                    "a running radio stopped but for an ending with the data stopped",
                                );
                            }
                            if *name == "stop" && at.data == "flowing" && !gate_closed {
                                problem(
                                    "the radio's stop asked with the data flowing and the gate open",
                                );
                            }
                        }
                        Item::Answer { name, answer } => {
                            if let Some(given) = gives(name, answer) {
                                held = given;
                            }
                            if (*name, *answer) == ("units_home", "home") {
                                home = true;
                            }
                            if wakes(name, answer) {
                                woken = true;
                            }
                        }
                        Item::Tell(name, at) => {
                            if *name == "end_tokens" {
                                if tok {
                                    problem("the tokens' end told twice");
                                }
                                tok = true;
                            }
                            if *name == "stop_network" {
                                net = true;
                            }
                            if *name == "data_flows" {
                                if at.data != "flowing" || told {
                                    problem("the data told to flow twice, or not from a stop");
                                }
                                told = true;
                            }
                        }
                        Item::End(name, permit) => {
                            if *name == "ok/started" {
                                // The radio runs: the controller opens the gate.
                                gate_closed = false;
                            }
                            returned = *permit;
                            ends += 1;
                            if opened.is_none() {
                                problem("an end with no request");
                            }
                            opened = None;
                        }
                        Item::Report(_) => {}
                    }
                }
                if ends > 1 {
                    problem("two ends in a step");
                }
                if inp.kind == "needs_stop" && s.pos != "stopping" {
                    if !asked.contains(&"stop") {
                        problem("a stop indication not answered by the radio's stop in its step");
                    }
                    if asked
                        .iter()
                        .any(|name| matches!(*name, "start" | "retune" | "retire" | "release"))
                    {
                        problem("a stop indication answered by more than a stop");
                    }
                    let data_first = asked
                        .iter()
                        .position(|name| *name == "stop_data")
                        .zip(asked.iter().position(|name| *name == "stop"))
                        .is_some_and(|(data, stop)| data < stop);
                    if s.pos == "running" && !data_first {
                        problem("a stop indication stopped the radio before the data");
                    }
                    let reported = trace
                        .iter()
                        .any(|item| matches!(item, Item::Report(what) if what == "interrupted"));
                    if (s.pos == "running") != reported {
                        problem("the controller was not told that the run was interrupted");
                    }
                }
                if (s.data != "flowing" && ns.data == "flowing") != told {
                    problem("the data plane was not told what the machine holds");
                }
                longest = longest.max(asked.len());
                if holds(ns.pos) != held {
                    problem("right not accounted");
                }
                if rest == "round" && ns == s && ends == 0 {
                    problem("a round with nothing changed");
                }
                if matches!(ns.goal, None | Some("service")) != opened.is_none() {
                    problem("goal and open request differ");
                }
                if raw
                    != (if rest == "round" {
                        Rest::Round
                    } else {
                        Rest::Wake(after)
                    })
                {
                    problem("a rest names the wrong instant");
                }
                if ends > 0 {
                    if returned != permit(&ns) {
                        problem("an end returned a permit of another class");
                    }
                    holds_permit = returned;
                }
                if opened.is_none() && holds_permit == Some("live") && !live {
                    problem("a live permit with the tokens ended");
                }
                let kinds: Vec<String> = trace
                    .iter()
                    .filter_map(|item| match item {
                        Item::Ask { name, .. } | Item::Tell(name, _) | Item::End(name, _) => {
                            Some((*name).to_string())
                        }
                        Item::Report(what) => Some(what.clone()),
                        Item::Answer { .. } => None,
                    })
                    .collect();
                let answers: Vec<&'static str> = trace
                    .iter()
                    .filter_map(|item| match item {
                        Item::Answer { answer, .. } => Some(*answer),
                        _ => None,
                    })
                    .collect();
                table
                    .entry((s.pos, s.goal.unwrap_or("-"), inp.last()))
                    .or_default()
                    .insert((answers, ns.pos, kinds, rest));
                let next = Env {
                    s: ns,
                    budget: (budget2.0, budget2.1, budget2.2, budget2.3 - used),
                    open: opened,
                    tok,
                    net,
                    turn: rest != "wake" || woken,
                    permit: holds_permit,
                    live,
                    gate_closed,
                };
                outs.push(next);
                if seen.insert(next) {
                    queue.push_back(next);
                }
            }
        }
        edges.insert(env, outs);
    }
    let rest_states: HashSet<Env> = seen.iter().copied().filter(quiet).collect();
    let mut back: HashMap<Env, Vec<Env>> = HashMap::new();
    for (a, outs) in &edges {
        for b in outs {
            back.entry(*b).or_default().push(*a);
        }
    }
    let mut good = rest_states.clone();
    let mut queue: VecDeque<Env> = rest_states.into_iter().collect();
    while let Some(b) = queue.pop_front() {
        for a in back.get(&b).into_iter().flatten() {
            if good.insert(*a) {
                queue.push_back(*a);
            }
        }
    }
    let dead = seen.iter().filter(|e| !good.contains(e)).count();
    let machine_states = seen.iter().map(|e| e.s).collect::<HashSet<_>>().len();
    Search {
        seen: seen.len(),
        machine_states,
        longest,
        problems,
        dead,
        table,
    }
}

/// The search's output in the model's `--table` form.
fn printed(search: &Search) -> String {
    let ways: usize = search.table.values().map(BTreeSet::len).sum();
    let mut out = format!(
        "environment states visited: {}; machine states: {}; ways of a step: {}; the longest step asks {}\n",
        search.seen, search.machine_states, ways, search.longest
    );
    for (kind, count) in &search.problems {
        out.push_str(&format!("PROBLEM {kind}: {count}\n"));
    }
    out.push_str(&format!("dead ends: {}\n", search.dead));
    for ((pos, goal, inp), outs) in &search.table {
        for (answers, to, kinds, rest) in outs {
            let answers = if answers.is_empty() {
                "—".to_string()
            } else {
                answers.join(", ")
            };
            let kinds = if kinds.is_empty() {
                "—".to_string()
            } else {
                kinds.join(", ")
            };
            out.push_str(&format!(
                "| {pos} | {goal} | {inp} | {answers} | {to} | {kinds} | {rest} |\n"
            ));
        }
    }
    out
}

/// Run `body` with the closed gate of one installation, the brand every
/// machine of the search is built with.
fn with_gate<R>(body: impl for<'id> FnOnce(&GateClosed<'id>) -> R) -> R {
    let future = core::pin::pin!(oer_protocols_radio_port::branded(
        async |mint: oer_protocols_radio_port::Mint<
            '_,
            oer_protocols_ieee80211_contracts_port::GatePool,
        >| {
            let (closed, _issuer) = mint.into_pools();
            body(&closed)
        }
    ));
    let mut cx = core::task::Context::from_waker(core::task::Waker::noop());
    match core::future::Future::poll(future, &mut cx) {
        core::task::Poll::Ready(value) => value,
        core::task::Poll::Pending => panic!("a gate's mint performs no async operation"),
    }
}

#[test]
fn the_search_over_the_machine_finds_the_models_table() {
    let search = with_gate(|gate| explore((3, 1, 1, 2), gate));
    assert!(search.problems.is_empty(), "{:?}", search.problems);
    assert_eq!(search.dead, 0, "dead ends");
    assert_eq!(search.longest, 4, "the most asks of a step");
    let expected = include_str!("../tests/model-table.txt");
    let found = printed(&search);
    for (line, (found, expected)) in found.lines().zip(expected.lines()).enumerate() {
        assert_eq!(found, expected, "line {}", line + 1);
    }
    assert_eq!(
        found.lines().count(),
        expected.lines().count(),
        "the table's length"
    );
}

#[test]
fn the_search_holds_at_the_models_wider_bounds() {
    // The states and ways of a step the model finds at each bound
    // (`python3 -I design/installation-machine-model-next.py <bound>`).
    for (budget, model_seen, model_ways) in [
        ((3, 1, 1, 3), 1_197, 427),
        ((4, 2, 2, 3), 7_110, 445),
        ((3, 2, 3, 4), 4_635, 445),
    ] {
        let search = with_gate(|gate| explore(budget, gate));
        assert!(
            search.problems.is_empty(),
            "{budget:?}: {:?}",
            search.problems
        );
        assert_eq!(search.dead, 0, "{budget:?}: dead ends");
        assert_eq!(search.seen, model_seen, "{budget:?}: the states visited");
        let ways: usize = search.table.values().map(BTreeSet::len).sum();
        assert_eq!(ways, model_ways, "{budget:?}: the ways of a step");
    }
}

#[test]
fn a_placed_machine_halts_a_stopped_radio_at_once_and_returns_a_live_permit() {
    let (_, stopped, right) = key();
    let mut place = MaybeUninit::uninit();
    let (machine, permit) = M::place(&mut place, stopped, right, ());
    let step = machine.step(
        Input::Request(Request::halt(Live::Stopped(permit), None)),
        NOW,
    );
    let Step::Ended(Ended::Request(Ok(End::Halted), Permit::Live(Live::Stopped(_))), resume) = step
    else {
        panic!("a stopped radio with its data home halts at once");
    };
    assert!(matches!(resume.go(), Step::Rest(Rest::Wake(None))));
}

#[test]
fn a_started_radio_hands_the_data_its_rights_and_a_running_permit() {
    let (key, stopped, right) = key();
    let mut place = MaybeUninit::uninit();
    let (machine, permit) = Machine::<'_, u8, u32>::place(&mut place, stopped, right, 7);
    let Step::Start(StartAsk::Begin(stopped, CHANNEL), resume) =
        machine.step(Input::Request(Request::run(permit, CHANNEL, None)), NOW)
    else {
        panic!("a run of a stopped radio asks its start");
    };
    let Step::Tell(Tell::DataFlows(7), resume) =
        resume.answer(StartPoll::Running(key.started(key.start(stopped))))
    else {
        panic!("the data is told it flows, with its rights");
    };
    let Step::Ended(Ended::Request(Ok(End::Started), Permit::Live(Live::Running(_))), _) =
        resume.go()
    else {
        panic!("the start ends with a permit of a running radio");
    };
}
